/* Pair Chrome storage to KoneWebTranslator Studio. The connection code is
 * generated by Studio and never hardcoded into the extension. */
'use strict';
(() => {
  const root=document.getElementById('kwt-studio-link');
  if(!root)return;
  const code=root.querySelector('#kwt-studio-code');
  const message=root.querySelector('#kwt-studio-message');
  const status=root.querySelector('#kwt-studio-status');
  async function send(type,extra={}){
    const reply=await chrome.runtime.sendMessage({type,...extra});
    if(!reply?.ok)throw Error(reply?.error||'연결 실패');
    return reply.result;
  }
  const feedback=(s,fail=false)=>{message.textContent=s;message.style.color=fail?'#dc2626':'#0e9f6e'};
  async function refresh(){
    const v=await send('KWT_STUDIO_LINK_STATUS');
    status.textContent=v.paired?`Studio 연결됨 · 설정 버전 ${v.revision}`:'Studio 연결 전';
  }
  root.querySelector('#kwt-studio-pair').addEventListener('click',async()=>{
    try{const r=await send('KWT_STUDIO_PAIR',{code:code.value.trim()});
      feedback('연결 성공. 기존 Chrome 규칙과 설정을 Studio에 동기화했습니다. (버전 '+r.revision+')');
      code.value='';await refresh();
    }catch(e){feedback(String(e.message||e),true)}
  });
  root.querySelector('#kwt-studio-now').addEventListener('click',async()=>{
    try{const r=await send('KWT_STUDIO_SYNC_NOW');
      feedback(r.paired?'설정 동기화 완료':'연결 전입니다. 먼저 연결 코드를 입력하세요.');await refresh();
    }catch(e){feedback(String(e.message||e),true)}
  });
  root.querySelector('#kwt-studio-unlink').addEventListener('click',async()=>{
    if(!confirm('이 Chrome 확장앱의 Studio 연결 토큰만 삭제할까요? 수집 규칙과 Chrome 권한은 유지됩니다.'))return;
    try{await send('KWT_STUDIO_UNLINK');feedback('이 브라우저 연결 해제됨. Studio 측 연결 해제도 필요할 수 있습니다.');await refresh();}
    catch(e){feedback(String(e.message||e),true)}
  });
  refresh().catch(e=>feedback(String(e),true));
})();
